#include <bits/stdc++.h>

using namespace std;

int n, k, c[500010], ans, tot;
queue<int> q;

int main() {
    cin >> n >> k;
    q.push(0);
    while (k--) q.push(0);

    for (int i = 1; i <= n; ++i) cin >> c[i];
    sort(c + 1, c + n + 1);

    for (int i = n; i > 0; --i) {
        int x = q.front();
        q.pop();
        tot += x;
        q.push(x + c[i]);
    }

    cout << tot << endl;
    return 0;
}

